tips[2930]={d="Wszyscy oprócz Lepers to elita, poziom 24-26."}
tips[2933]={t="Przy butelkach stoją Witherbark Scalpers i Zealots (poziom 40-42); Zul'arek Hatefowler (elita 43) jest w okolicy 32,57."}
