tips[95773]={t="Wymaga oddania The Gurubashi Legends of Old.",d="Szansa jest niska, a nagi są pod wodą; weź grupę albo coś do oddychania.",h="Wymaga oddania Enemies in the Water i Locating the Lost City."}
